import { performance, PerformanceObserver } from "node:perf_hooks";
function main(): void {
  const o = new PerformanceObserver((list) => { console.log("named", list.getEntriesByName("c").length, list.getEntriesByType("mark").length, list.getEntriesByName("c", "mark")[0].entryType); });
  o.observe({ entryTypes: ["mark"] });
  performance.mark("c");
  setTimeout(() => o.disconnect(), 20);
}
